"ssoProvider\")\n}\n\nmodel Apikey {\n  id                  String    @id\n  configId            String    @default(\"default\")\n  name                String?\n  start               String?\n  referenceId         String\n  user                User      @relation(fields: [referenceId], references: [id], onDelete: Cascade)\n  prefix              String?\n  key                 String\n  refillInterval      Int?\n  refillAmount        Int?\n  lastRefillAt        DateTime?\n  enabled             Boolean?  @default(true)\n  rateLimitEnabled    Boolean?  @default(true)\n  rateLimitTimeWindow Int?\n  rateLimitMax        Int?\n  requestCount        Int?      @default(0)\n  remaining           Int?\n  lastRequest         DateTime?\n  expiresAt           DateTime?\n  createdAt           DateTime\n  updatedAt           DateTime\n  permissions         String?\n  metadata            String?\n\n  @@index([referenceId])\n  @@index([configId])\n  @@index([key])\n  @@map(\"apikey\")\n}\n",
